SELECT fhir_Practitioner.Id, fhir_Practitioner.Identifier, fhir_Practitioner.Active, fhir_Practitioner.NameFamily, fhir_Practitioner.NameGiven, fhir_Practitioner.Qualification, fhir_Practitioner.Specialty, fhir_Practitioner.TelecomEmail, fhir_Practitioner.TelecomPhone FROM fhir_Practitioner WHERE fhir_Practitioner.Specialty LIKE '%' || @specialty || '%' ORDER BY fhir_Practitioner.NameFamily , fhir_Practitioner.NameGiven 